pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint56 fuzzChangeFee, uint128 virtualBase, uint128 virtualNft, uint16 feeRate, bytes32 merkleRoot, bool useOracle, bool payRoyalties) public {
        feeRate = uint16(feeRate % 6000);

        address baseToken = address(0);
        address nft = address(this);

        bool ok;
        try c.initialize(baseToken, nft, virtualBase, virtualNft, fuzzChangeFee, feeRate, merkleRoot, useOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.changeFee() == fuzzChangeFee);
        }
    }
}
